'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

const NOTIFICATION_PREF_COOKIE = 'notifications_enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const isEnabled = cookieStore.get(NOTIFICATION_PREF_COOKIE)?.value === 'true'

  cookieStore.set(NOTIFICATION_PREF_COOKIE, String(!isEnabled), {
    httpOnly: true,
    path: '/',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 365,
  })

  refresh()
}

