import { cookies } from 'next/headers'

import { toggleNotificationPreference } from './actions'

const NOTIFICATION_PREF_COOKIE = 'notifications_enabled'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsEnabled =
    cookieStore.get(NOTIFICATION_PREF_COOKIE)?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>.
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'Off' : 'On'}
        </button>
      </form>
    </main>
  )
}

